INSERT INTO `ann` (`id`, `ann`) VALUES
(1, 'Effective immediately the point system has changed, the total available points will remain 50. The winner of each daily contest will be issued 25 base points, and the algorithm will divide the remaining 25 between first and second using the same criteria as before.  The winners email should reflect this change.  This change is in beta so we may experience some glitches in the next few days as I hone the algorithm. \r\n\r\nRemember: the new game is not all about just finding as much money as humanly possible, it\'s a strategy to gain points, and penalties are built into the algorithm in an attempt to make the game more interesting...  \r\n\r\nThe changes to the game are implemented now... happy hunting!');

