--
-- Table structure for table `loads`
--

CREATE TABLE `loads` (
  `id` int(7) NOT NULL,
  `date` datetime NOT NULL,
  `frtl` varchar(7) NOT NULL DEFAULT '0000000',
  `pickup` varchar(10) NOT NULL,
  `delivery` varchar(30) NOT NULL,
  `split` int(2) NOT NULL DEFAULT '0',
  `add` int(2) NOT NULL DEFAULT '0',
  `demurrage` int(4) NOT NULL DEFAULT '0',
  `paid` int(1) NOT NULL DEFAULT '0',
  `demPaid` int(1) NOT NULL DEFAULT '0',
  `weekend` int(1) NOT NULL DEFAULT '0',
  `note` varchar(1000) DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

